import {Game} from './engine.js?v=0.29.0';
import {Renderer} from './renderer.js?v=0.29.0';
import {ProductionArt} from './production-art.js?v=0.29.0';
import {productionManifest} from './production-manifest.js?v=0.29.0';
import {BOSS_CATALOG,getBoss,getMission} from './campaign.js?v=0.29.0';
import {productionLaunchPlan,preloadLaunchPlan} from './launch-gate.js?v=0.29.0';
const $=id=>document.getElementById(id),canvas=$('stage'),art=new ProductionArt({manifest:productionManifest});
const renderer=new Renderer(canvas,{productionArt:art});renderer.atmosphereEnabled=false;renderer.minimapEnabled=false;renderer.shakeEnabled=false;renderer.zoom=1.5;
const names={walker:'보행자',runner:'질주자',shield:'방패병',screamer:'비명자',gas:'가스 운반자',elite:'정예',collector:'수집자'};
const choices=[...BOSS_CATALOG.map(b=>({id:b.id,name:`${String(getMission(b.missionId).index+1).padStart(2,'0')} · ${b.role==='mid'?'중간':'최종'} · ${b.name}`,kind:'boss',missionId:b.missionId})),...Object.entries(names).map(([id,name])=>({id:`enemy:${id}`,name:`일반 적 · ${name}`,kind:'enemy',type:id})),...['shotgun','nailgun'].map(weapon=>({id:`hero:${weapon}`,name:`생존자 · ${weapon==='shotgun'?'산탄총':'전기 못총'}`,kind:'hero',weapon}))];
for(const group of[['보스',choices.filter(c=>c.kind==='boss')],['일반 적',choices.filter(c=>c.kind==='enemy')],['생존자',choices.filter(c=>c.kind==='hero')]]){const element=document.createElement('optgroup');element.label=group[0];for(const choice of group[1]){const option=document.createElement('option');option.value=choice.id;option.textContent=choice.name;element.append(option);}$('actor').append(element);}
for(let i=0;i<16;i++){const option=document.createElement('option');option.value=String(i);option.textContent=`방향 ${String(i).padStart(2,'0')} · ${i*22.5}°`;$('direction').append(option);}$('direction').value='2';
const state={game:null,actor:null,corpse:null,choice:null,ready:false,playing:false,clock:0,age:0,serial:0,mode:'pose',pose:'idle',direction:2,observed:new Set(),lastDraw:null,pauseSignature:null,keys:new Set(),pointer:{x:1200,y:800},shooting:false};
const rgba=metadata=>metadata.atlas.width*metadata.atlas.height*4/1048576;
const mappingIds=mapping=>typeof mapping==='string'?[mapping]:Object.values(mapping||{});
const selectionIds=()=>state.choice?.kind==='hero'?mappingIds(art.manifest.characters[`survivor-${state.choice.weapon}`]):state.choice?.kind==='boss'?mappingIds(art.manifest.bosses[state.choice.id]):mappingIds(art.manifest.enemies[state.choice?.type]);
const originalDraw=art.drawFrame.bind(art);art.drawFrame=(context,selected,options)=>{const painted=originalDraw(context,selected,options);if(painted&&selected&&selectionIds().includes(selected.id)){state.lastDraw=selected;state.observed.add(selected.frame.sample);}return painted;};
for(const method of['bossFrame','enemyFrame','characterFrame']){const original=art[method].bind(art);art[method]=(key,actor,options={})=>{
  if(state.mode==='pose'&&actor===state.actor){const m=actionMetadata(),duration=poseDuration(m),progress=Math.min(1,state.age/Math.max(.01,duration));
    options={...options,pose:state.pose,phase:state.pose==='walk'||state.pose==='run'?state.age/Math.max(.01,duration)*Math.PI*2:undefined,animationTime:state.age};
    if(state.choice.kind==='hero')options.visualAction={hitFlash:state.pose==='hit'?.12*(1-progress):0,attackState:state.pose==='attack'?'charge':'walk',attackTime:.12*(1-progress),dead:state.pose==='death'};
  }return original(key,actor,options);};}
const originalCorpse=renderer.nativeCorpseFrame.bind(renderer);renderer.nativeCorpseFrame=(corpse,game,now)=>state.mode==='pose'&&corpse===state.corpse?originalCorpse(corpse,{...game,state:'paused'},now):originalCorpse(corpse,game,now);
function actionMetadata(){const ids=selectionIds();return ids.map(id=>art.get(id)?.metadata).find(m=>m?.animation?.clips)||ids.map(id=>art.get(id)?.metadata).find(Boolean);}
function poseDuration(metadata=actionMetadata()){const alias=state.pose==='run'?'walk':state.pose;return metadata?.animation?.clips?.[alias]?.duration||metadata?.animation?.duration||1.2;}
function signature(){const g=state.game;if(!g)return'';return JSON.stringify({time:g.time,state:g.state,player:g.player,enemies:g.enemies,corpses:g.corpses,result:g.result,random:g.random.getState(),visual:g.visualRandom.getState()});}
function shortHash(text){let h=2166136261;for(let i=0;i<text.length;i++)h=Math.imul(h^text.charCodeAt(i),16777619);return(h>>>0).toString(16).padStart(8,'0');}
function resetInputs(){state.keys.clear();state.shooting=false;}
function setPlaying(playing){state.playing=playing;resetInputs();if(state.game&&state.mode==='combat'){if(playing)state.game.resume();else state.game.pause();}state.pauseSignature=playing?null:signature();$('play').textContent=playing?'일시정지':state.mode==='combat'?'실제 전투 진행':'동작 재생';$('play').setAttribute('aria-pressed',String(playing));}
function legalSpot(game,actor){const p=game.player;for(let ring=0;ring<5;ring++)for(let i=0;i<16;i++){const a=i/16*Math.PI*2,d=115+ring*35,x=p.x+Math.cos(a)*d,y=p.y+Math.sin(a)*d;if(!game.blocked(x,y,actor.r+3)){actor.x=x;actor.y=y;return;}}}
async function prepare(){const serial=++state.serial;setPlaying(false);state.ready=false;state.observed.clear();state.lastDraw=null;$('load-state').textContent='원본 에셋과 현재 장면 로딩 중';$('load-state').className='meter';canvas.dataset.qaReady='loading';const choice=choices.find(c=>c.id===$('actor').value)||choices[0];
 const game=new Game({seed:764208,weapon:choice.weapon||'shotgun',...(choice.kind==='boss'?{missionId:choice.missionId}:{}),stageDuration:1e9});game.enemies=[];game.spawnClock=1e9;game.player.invul=9999;let actor;
 if(choice.kind==='boss'){actor=game.spawnMissionBoss('mid');if(getBoss(choice.id).role==='final'){game.damageEnemy(actor,actor.hp);actor=game.spawnMissionBoss('final');game.corpses=[];}actor.skillCd=1.2;legalSpot(game,actor);}
 else if(choice.kind==='enemy'){actor=game.spawnEnemy(choice.type,400);legalSpot(game,actor);}
 else{actor=game.player;const enemy=game.spawnEnemy('walker',400);if(enemy)legalSpot(game,enemy);}
 actor.angle=Number($('direction').value)*Math.PI/8;game.player.angle=actor.angle;
 try{const mission=getMission(game.missionId),plan=productionLaunchPlan({manifest:art.manifest,weapon:game.player.weapon,mission,world:game.world});
  const ids=new Set([...plan.playerIds,...mappingIds(choice.kind==='boss'?art.manifest.bosses[choice.id]:choice.kind==='enemy'?art.manifest.enemies[choice.type]:art.manifest.enemies.walker)]);
  const environments=new Set(Object.values(art.manifest.environment||{}));for(const id of plan.assetIds)if(environments.has(id))ids.add(id);
  const filtered={...plan,assetIds:[...ids]};if(!await preloadLaunchPlan(renderer,filtered))throw new Error('실제 atlas 로딩 또는 검증 실패');if(serial!==state.serial)return;
  art.releaseUnusedAssets(filtered.assetIds);state.game=game;state.actor=actor;state.corpse=null;state.choice=choice;state.clock=0;state.age=0;state.mode=$('mode').value;state.pose=$('pose').value;state.direction=Number($('direction').value);state.ready=true;renderer.cameraReady=false;renderer.nativeCorpseEndClocks=new WeakMap();renderer.nativePlayerEndClocks=new WeakMap();
  if(state.mode==='pose')applyInitialPose();game.pause();state.pauseSignature=signature();canvas.dataset.qaReady='ready';$('load-state').textContent='현재 장면 실제 렌더 준비 완료';$('scene-label').textContent=`${choice.name} / ${state.mode==='pose'?'동작 프리셋':'실제 전투'}`;updateDiagnostics();
 }catch(error){if(serial!==state.serial)return;canvas.dataset.qaReady='failed';$('load-state').textContent=error.message;$('load-state').className='meter error';$('diagnostics').textContent=error.stack||error.message;}}
function applyInitialPose(){const g=state.game,a=state.actor;if(!g||!a)return;g.state='playing';
 if(state.pose==='death'){if(state.choice.kind==='hero'){g.player.invul=0;g.hurtPlayer(g.player.hp);}else{g.damageEnemy(a,a.hp);state.corpse=g.corpses.find(c=>c.seed===a.id)||null;}}
 else if(state.pose==='hit'){if(state.choice.kind==='hero'){g.player.invul=0;g.hurtPlayer(1);}else g.damageEnemy(a,1);}
 else if(state.pose==='attack'&&state.choice.kind==='hero')g.shoot();
 updateManualPose();}
function updateManualPose(){const g=state.game,a=state.actor;if(!g||!a)return;const duration=poseDuration(),progress=Math.min(1,state.age/Math.max(.01,duration));g.time=state.clock;a.angle=state.direction*Math.PI/8;
 if(state.pose==='death'){if(state.corpse)state.corpse.time=Math.max(.001,state.corpse.duration-state.age);return;}
 if(state.choice.kind==='hero'){g.flash=state.pose==='hit'?.35*(1-progress):0;a.recoil=state.pose==='attack'?.12*(1-progress):0;}
 else{a.attackState=state.pose==='windup'?'windup':state.pose==='attack'?'charge':'walk';const boss=getBoss(a.bossKey),skill=boss?.skill;const attackDuration=state.pose==='windup'?(skill?.windup||1.15):(skill?.duration||.95);a.attackTime=attackDuration*(1-progress);a.hitFlash=state.pose==='hit'?.12*(1-progress):0;a.attackCd=0;if(a.type==='screamer')a.skillCd=3;}
 a.walkPhase=state.age/Math.max(.01,duration)*Math.PI*2;}
function updateDiagnostics(){const selected=state.lastDraw,g=state.game;if(!g)return;const metadata=selected?.metadata,span=metadata?.animation?.clips&&Object.entries(metadata.animation.clips).find(([,v])=>selected.frame.sample>=v.start&&selected.frame.sample<v.start+v.count)?.[0];const pausedMatch=!state.playing&&state.pauseSignature===signature();
 Object.assign(canvas.dataset,{qaActor:state.choice.id,qaMode:state.mode,qaPose:state.pose,qaPlaying:String(state.playing),qaAsset:selected?.id||'',qaFrame:String(selected?.frame.index??-1),qaSample:String(selected?.frame.sample??-1),qaDirection:String(selected?.frame.direction??-1),qaClip:span||metadata?.animation?.name||'static',qaSource:metadata?.source?.file||'',qaPacking:metadata?.atlas.packing||'grid',qaFrames:String(metadata?.frames.length||0),qaNativePainted:String(!!selected),qaObservedSamples:JSON.stringify([...state.observed].sort((a,b)=>a-b)),qaPauseUnchanged:String(pausedMatch),qaSignature:shortHash(signature()),qaGameState:g.state,qaGameTime:g.time.toFixed(4)});
 $('pause-result').textContent=state.playing?'동작 진행 중':pausedMatch?'일시정지 검사: Game·캐릭터·양쪽 RNG 상태가 그대로입니다.':'일시정지 직후 상태 확인 중';
 $('diagnostics').textContent=`${state.choice.name} | ${state.mode==='pose'?'격리된 렌더 프리셋':'실제 Game.tick'} | ${state.playing?'재생':'정지'}\n현재 네이티브: ${selected?.id||'대기'} | 클립 ${span||metadata?.animation?.name||'정적'} | 방향 ${selected?.frame.direction??'-'} | 샘플 ${selected?.frame.sample??'-'}\nGLB ${metadata?.source?.file||'-'} | skins ${metadata?.source?.rig?.skins??'-'} · bones ${metadata?.source?.rig?.bones??'-'} | 전체 ${metadata?.frames.length||0}프레임\n${metadata?`${metadata.atlas.width}×${metadata.atlas.height} · RGBA ${rgba(metadata).toFixed(2)}MiB · ${metadata.atlas.packing||'고정 셀'}`:'에셋 준비 중'} | 관찰한 샘플 ${state.observed.size}개\n게임 ${g.state} · ${g.time.toFixed(3)}초 | 세이브/계정/스토리지 접근 없음 | 상태 지문 ${shortHash(signature())}`;}
$('actor').addEventListener('change',prepare);$('mode').addEventListener('change',prepare);$('pose').addEventListener('change',prepare);$('restart').addEventListener('click',prepare);
$('previous').addEventListener('click',()=>{const i=choices.findIndex(c=>c.id===$('actor').value);$('actor').value=choices[(i-1+choices.length)%choices.length].id;prepare();});$('next').addEventListener('click',()=>{const i=choices.findIndex(c=>c.id===$('actor').value);$('actor').value=choices[(i+1)%choices.length].id;prepare();});
$('direction').addEventListener('change',()=>{state.direction=Number($('direction').value);if(state.actor)state.actor.angle=state.direction*Math.PI/8;state.pauseSignature=signature();});$('zoom').addEventListener('change',()=>{renderer.zoom=Number($('zoom').value);});$('play').addEventListener('click',()=>{if(state.ready)setPlaying(!state.playing);});
function actualAction(action){if(!state.ready)return;const g=state.game,a=state.actor;state.mode='combat';$('mode').value='combat';if(g.state==='paused')g.resume();if(g.state!=='playing')return;
 if(action==='shoot')g.shoot();if(action==='damage'){if(state.choice.kind==='hero'){g.player.invul=0;g.hurtPlayer(5);}else g.damageEnemy(a,Math.max(1,a.maxHp*.08));}if(action==='kill'){if(state.choice.kind==='hero'){g.player.invul=0;g.hurtPlayer(g.player.hp);}else{g.damageEnemy(a,a.hp);state.corpse=g.corpses.find(c=>c.seed===a.id);}}setPlaying(true);$('scene-label').textContent=`${state.choice.name} / 실제 엔진 반응`;}
for(const id of['shoot','damage','kill'])$(id).addEventListener('click',()=>actualAction(id));
canvas.addEventListener('pointermove',event=>{const r=canvas.getBoundingClientRect();state.pointer=renderer.screenToWorld(event.clientX-r.left,event.clientY-r.top);});canvas.addEventListener('pointerdown',event=>{canvas.focus();state.shooting=true;canvas.setPointerCapture(event.pointerId);});canvas.addEventListener('pointerup',()=>{state.shooting=false;});canvas.addEventListener('pointercancel',resetInputs);
canvas.addEventListener('keydown',event=>{if(['KeyW','KeyA','KeyS','KeyD','Space'].includes(event.code)){state.keys.add(event.code);event.preventDefault();}});canvas.addEventListener('keyup',event=>state.keys.delete(event.code));window.addEventListener('blur',()=>setPlaying(false));document.addEventListener('visibilitychange',()=>{if(document.hidden)setPlaying(false);});new ResizeObserver(()=>renderer.resize()).observe(canvas.parentElement);
let last=0,diagnosticClock=0;function frame(now){const dt=last?Math.min(.05,(now-last)/1000):0;last=now;if(state.ready){if(state.playing){state.clock+=dt;if(state.mode==='pose'){state.age+=dt;const duration=poseDuration();if(state.pose!=='death'&&state.age>duration+.45){state.age=0;}updateManualPose();}else{const input={moveX:Number(state.keys.has('KeyD'))-Number(state.keys.has('KeyA')),moveY:Number(state.keys.has('KeyS'))-Number(state.keys.has('KeyW')),shoot:state.shooting,aimX:state.pointer.x,aimY:state.pointer.y,dash:state.keys.has('Space')};state.game.tick(dt,input);state.keys.delete('Space');}}
 renderer.render(state.game,{},state.clock);diagnosticClock+=dt;if(diagnosticClock>.1||!state.playing){diagnosticClock=0;updateDiagnostics();}}requestAnimationFrame(frame);}prepare();requestAnimationFrame(frame);
